// GENERATED by build.sh -- edit tests/surface-geometry/test.js, not this file.
// Conformance harness: how a test says what it found.
//
// The result channel is `console.error` with a structured prefix. That looks
// crude and it is the deliberate choice: it is the ONE channel that already
// works identically on every platform Migo runs on -- Android through JNI,
// C-ABI hosts with no JVM, the Linux player, Windows -- with no new platform
// surface to build, maintain, or forget to port. (`console.log` is filtered by
// EMUI on real Huawei devices; `console.error` is not.)
//
// Everything below is deliberately dependency-free and runs inside the game
// bundle, because the whole point is that the same bundle produces the same
// verdict wherever it runs.
//
// The API these bundles call is `migo.*`, not `wx.*`. `migo` is the only
// capability surface the engine installs; the mini-game-platform globals come
// from a separate adapter package that a host loads if it wants them. Bundles
// here written against `wx` stopped running entirely when that namespace left
// the engine -- every test died on `ReferenceError: wx is not defined` before
// its first assertion, and the suite reported "0 assertions" rather than a
// failure anyone would read as one. A suite must test the engine's own surface,
// or it tests whichever adapter happened to be loaded.

(() => {
    const PREFIX = "[conformance]";
    const results = [];
    let finished = false;

    const emit = (line) => console.error(PREFIX, line);

    /// Report one assertion. `detail` should carry the numbers, not just a verdict:
    /// a failure that says "expected #ff00ff, got #000000 at (360,640)" is
    /// actionable from a log file on a device you cannot attach a debugger to.
    function check(id, passed, detail) {
        results.push({ id, passed: !!passed });
        emit(`${passed ? "PASS" : "FAIL"} ${id} ${detail || ""}`.trimEnd());
    }

    /// Compare two pixel buffers that must be identical *within this run*.
    ///
    /// This is the reftest primitive, and it is the most valuable one here: it is
    /// platform-independent by construction. Two ways of drawing the same thing
    /// must agree, whatever the GPU does to both of them -- so it survives Mali vs
    /// Adreno vs SwiftShader vs ANGLE, where a golden image cannot.
    function checkSameRender(id, a, b, tolerance) {
        const tol = tolerance || 0;
        if (a.length !== b.length) {
            check(id, false, `buffer lengths differ: ${a.length} vs ${b.length}`);
            return;
        }
        let worst = 0;
        let worstAt = -1;
        for (let i = 0; i < a.length; i++) {
            const d = Math.abs(a[i] - b[i]);
            if (d > worst) { worst = d; worstAt = i; }
        }
        check(
            id,
            worst <= tol,
            worst <= tol
                ? `max channel delta ${worst} <= ${tol}`
                : `max channel delta ${worst} > ${tol} at byte ${worstAt} (px ${Math.floor(worstAt / 4)})`,
        );
    }

    /// Assert one pixel. Sampling beats whole-frame comparison for geometry and
    /// colour: it says which pixel was wrong, and it does not care how the driver
    /// anti-aliased the edge two pixels away.
    function checkPixel(id, ctx, x, y, expected, tolerance) {
        const tol = tolerance === undefined ? 2 : tolerance;
        const px = ctx.getImageData(x, y, 1, 1).data;
        const got = [px[0], px[1], px[2], px[3]];
        const ok = expected.every((want, i) => Math.abs(got[i] - want) <= tol);
        check(id, ok, `at (${x},${y}) want [${expected}] +/-${tol}, got [${got}]`);
    }

    /// End the run. The runner keys off these lines rather than an exit code,
    /// because several of the hosts that must run this suite (a NativeActivity, an
    /// embedded session inside someone else's app) have no exit code to give.
    function done() {
        if (finished) return;
        finished = true;
        const failed = results.filter((r) => !r.passed);
        emit(`SUMMARY total=${results.length} failed=${failed.length}`);
        if (failed.length) emit(`FAILED-IDS ${failed.map((r) => r.id).join(",")}`);
        emit("DONE");
    }

    /// Run test bodies in order, then report. A throw is a failure with the message
    /// attached rather than a silent stop: a suite that dies quietly on one
    /// platform reads exactly like a suite that never ran.
    function run(tests) {
        // One test per frame, not all of them in one turn.
        //
        // Migo batches Canvas2D commands and resolves them at frame
        // boundaries, so a burst of draw-then-getImageData inside a single JS
        // turn is not what any real game does and not what the suite should
        // measure. Driving each test from its own rAF keeps every assertion on
        // the path content actually uses -- and stops the suite reporting
        // engine faults that are really artefacts of its own batching.
        // A body may return a promise, and then the next test does not start
        // until it settles. Lifecycle tests need this and pixel tests do not:
        // "the page went hidden and came back" is an event that arrives when the
        // host decides, not something a test body can drive to completion inside
        // one turn. Awaiting a non-promise is a microtask, so a synchronous body
        // still gets exactly one test per frame and its timing is unchanged --
        // which is why this is safe to add under the existing suites rather than
        // being a second runner they would drift away from.
        let index = 0;
        const step = async () => {
            if (index >= tests.length) {
                done();
                return;
            }
            const [id, body] = tests[index++];
            try {
                await body();
            } catch (error) {
                check(id, false, `threw ${error && error.name}: ${error && error.message}`);
            }
            requestAnimationFrame(step);
        };
        requestAnimationFrame(step);
    }

    // Deliberately a plain script assigned onto the global, not an ES module.
    //
    // Module resolution is exactly the kind of thing that can differ between a
    // bundle loaded by the Android SDK, a C-ABI host, and the Linux player -- and a
    // harness whose own loading is platform-dependent cannot tell you whether the
    // *engine* is platform-dependent. `build.sh` concatenates this ahead of each
    // test, so there is no resolution step at all.

    // Wrapped in an IIFE because build.sh concatenates this ahead of the test
    // in one scope: without it, a test writing `const { check } = ...` collides
    // with the harness's own `check` and the bundle dies at parse time with
    // "Identifier 'check' has already been declared". Caught on the runner's
    // first execution -- by the "no DONE line means failure" rule, which is the
    // one thing standing between this suite and reporting success for a bundle
    // that never ran.
    globalThis.Conformance = { check, checkPixel, checkSameRender, run, done, PREFIX };
})();

// Does content land where it asked to land, at the size it asked for?
//
// This is the backbone of the suite, not a nicety. Anti-aliasing and gradient
// dithering legitimately differ between GPUs; the coordinate system does not.
// Origin, Y direction, the extent of the drawable area, and the relationship
// between the canvas the content sees and the pixels the compositor gets are
// all exactly specified -- and getting any of them wrong does not produce a
// slightly different picture, it produces a game nobody can play.
//
// Migo has shipped every one of these wrong at least once: 2D content drawn
// into the top-left ninth of the screen after a surfaceChanged forced physical
// dimensions on a DPR-naive game; sprites filling the whole screen under Migo
// while WebView put them in the bottom 55%. Both are invisible to a test that
// only checks "did something get drawn".
//
// Every assertion samples well inside a region, never on an edge, so a correct
// implementation passes on any rasteriser.

const C = globalThis.Conformance;

const canvas = migo.createCanvas();
const ctx = canvas.getContext("2d");

// Re-read the canvas size at the start of every test body rather than once at
// load, because the surface can change size after the content is already
// running and a suite that cached the first value cannot see it.
//
// This is not a detail. Android delivers `surfaceCreated` at one size and
// `surfaceChanged` at another moments later -- the system bars hiding is the
// usual cause -- and `migo.createCanvas()` lands in between. A test holding the
// pre-change numbers draws and samples with the same stale pair, so every
// assertion agrees with itself and passes while the bottom of the real screen
// is a dead band. Reading fresh is also what a correct game does.
let W = 0;
let H = 0;
// A corner probe is sized as a fraction of the surface, not in absolute
// pixels: a fixed 40px box would be a different proportion of a 720p phone and
// a 1440p tablet, and on a small enough surface two probes would overlap and
// the test would report a failure that is really a bad test.
let PROBE = 0;
let INSET = 0;

const measure = () => {
    W = canvas.width;
    H = canvas.height;
    PROBE = Math.max(8, Math.floor(Math.min(W, H) / 10));
    INSET = Math.floor(PROBE / 2);
};

const RED = [255, 0, 0, 255];
const GREEN = [0, 255, 0, 255];
const BLUE = [0, 0, 255, 255];
const YELLOW = [255, 255, 0, 255];
const BLACK = [0, 0, 0, 255];

const clear = () => {
    ctx.save();
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.globalAlpha = 1;
    ctx.fillStyle = "#000000";
    ctx.fillRect(0, 0, W, H);
    ctx.restore();
};

const paintCorners = () => {
    clear();
    ctx.fillStyle = "#ff0000"; ctx.fillRect(0, 0, PROBE, PROBE);                     // top-left
    ctx.fillStyle = "#00ff00"; ctx.fillRect(W - PROBE, 0, PROBE, PROBE);             // top-right
    ctx.fillStyle = "#0000ff"; ctx.fillRect(0, H - PROBE, PROBE, PROBE);             // bottom-left
    ctx.fillStyle = "#ffff00"; ctx.fillRect(W - PROBE, H - PROBE, PROBE, PROBE);     // bottom-right
};

C.run([
    ["geometry/canvas-reports-a-usable-size", () => {
        measure();
        // Everything below divides by these. A canvas reporting 0, or a size
        // that is not an integer number of pixels, makes every later assertion
        // meaningless rather than failing honestly.
        C.check(
            "geometry/canvas-reports-a-usable-size",
            W > 0 && H > 0 && W === Math.floor(W) && H === Math.floor(H),
            `canvas ${W}x${H}`,
        );
    }],

    ["geometry/four-corners-are-distinct-and-correct", () => {
        measure();
        paintCorners();
        // Four different colours, because a single colour cannot tell a
        // correct layout from one that is mirrored, rotated 180 degrees, or
        // has its Y axis flipped -- all of which have shipped in real
        // runtimes, and all of which still "draw something in each corner".
        C.checkPixel("geometry/corner-top-left", ctx, INSET, INSET, RED);
        C.checkPixel("geometry/corner-top-right", ctx, W - 1 - INSET, INSET, GREEN);
        C.checkPixel("geometry/corner-bottom-left", ctx, INSET, H - 1 - INSET, BLUE);
        C.checkPixel("geometry/corner-bottom-right", ctx, W - 1 - INSET, H - 1 - INSET, YELLOW);
    }],

    ["geometry/the-whole-surface-is-drawable", () => {
        measure();
        // The failure this catches: content drawn into a fraction of the
        // surface because the backing store and the logical canvas disagree.
        // The picture looks right in its corner; the rest of the screen is
        // whatever the compositor had. Sampled one pixel in from the true
        // extremes, which is the part a shrunken drawable never reaches.
        paintCorners();
        C.checkPixel("geometry/extreme-top-left", ctx, 0, 0, RED);
        C.checkPixel("geometry/extreme-bottom-right", ctx, W - 1, H - 1, YELLOW);
        // ...and the middle must be background, not a fifth corner: if the
        // drawable were a quarter of the surface, the four probes would
        // collapse toward the centre and this would not be black.
        C.checkPixel("geometry/centre-is-background", ctx, W >> 1, H >> 1, BLACK);
    }],

    ["geometry/a-half-size-rect-is-half-the-surface", () => {
        measure();
        // Scale, independent of origin. A DPR applied twice, or not at all,
        // shows up here as a rect covering a quarter or the whole of the
        // surface while still starting at the right place.
        clear();
        const hw = Math.floor(W / 2);
        const hh = Math.floor(H / 2);
        ctx.fillStyle = "#ff00ff";
        ctx.fillRect(0, 0, hw, hh);
        const MAGENTA = [255, 0, 255, 255];
        // Deep inside the rect, and deep outside it on both axes.
        C.checkPixel("geometry/half-rect-inside", ctx, hw >> 1, hh >> 1, MAGENTA);
        C.checkPixel("geometry/half-rect-not-past-x", ctx, hw + (hw >> 1), hh >> 1, BLACK);
        C.checkPixel("geometry/half-rect-not-past-y", ctx, hw >> 1, hh + (hh >> 1), BLACK);
    }],

    ["geometry/aspect-ratio-is-not-squashed", () => {
        measure();
        // A square drawn in the shorter dimension must come back square. This
        // separates "wrong size" from "wrong aspect": a surface whose width and
        // height are scaled by different factors still passes the half-size
        // test above, and still ruins every circle and sprite in a real game.
        clear();
        const side = Math.floor(Math.min(W, H) / 4);
        ctx.fillStyle = "#00ffff";
        ctx.fillRect(0, 0, side, side);
        const CYAN = [0, 255, 255, 255];
        const inside = Math.max(1, side - 2);
        C.checkPixel("geometry/square-reaches-its-width", ctx, inside, 1, CYAN);
        C.checkPixel("geometry/square-reaches-its-height", ctx, 1, inside, CYAN);
        C.checkPixel("geometry/square-stops-past-width", ctx, side + 2, 1, BLACK);
        C.checkPixel("geometry/square-stops-past-height", ctx, 1, side + 2, BLACK);
    }],

    ["geometry/system-info-agrees-with-the-canvas", () => {
        measure();
        // The numbers content lays itself out with must describe the surface it
        // actually draws into. When they disagree, a game that positions a HUD
        // at `windowWidth - 100` puts it off-screen -- and nothing in the
        // rendering path is wrong, so no rendering test would ever catch it.
        const info = migo.getSystemInfoSync();
        const dpr = info.pixelRatio || 1;
        const expectedW = Math.round(info.windowWidth * dpr);
        const expectedH = Math.round(info.windowHeight * dpr);
        const logical = Math.abs(W - info.windowWidth) <= 1 && Math.abs(H - info.windowHeight) <= 1;
        const physical = Math.abs(W - expectedW) <= 1 && Math.abs(H - expectedH) <= 1;
        // Either convention is defensible; silently being neither is not.
        C.check(
            "geometry/system-info-agrees-with-the-canvas",
            logical || physical,
            `canvas ${W}x${H}, window ${info.windowWidth}x${info.windowHeight}, dpr ${dpr} ` +
            `(logical=${logical} physical=${physical})`,
        );
    }],
]);
